import { Config } from "../../Configs.js";
import { getGroupActiveMembers, getGroupControllerActive } from "../../endpoints.js";
import { drawTagsIntoTables, filterDataByHeaderType, pageNumbers, fillBtnPagination } from "../../tools.js";
import { InterfaceElement } from "../../types.js";
import { tableLayout, tableLayoutTemplate } from "./Layout.js";

// Local configs
const tableRows = Config.tableRows;
let currentPage = Config.currentPage;
const pageName = 'Empresas';
let infoPage = {
    count: 0,
    offset: Config.offset,
    currentPage: currentPage,
    search: ""
};

const GetCustomers = async () => {
    const response: any = await getGroupActiveMembers(infoPage.search, infoPage.offset, Config.tableRows);
    infoPage.count = response?.totalElements ?? 0;
    return response?.content ?? [];
};

export class SelectCustomer {
    private dialogContainer: InterfaceElement = document.getElementById('app-dialogs');
    private siebarDialogContainer: InterfaceElement = document.getElementById('entity-editor-container');
    private appContainer: InterfaceElement = document.getElementById('datatable-container');
        
    public async render(offset: any, actualPage: any, search: any) {
        infoPage.offset = offset;
        infoPage.currentPage = actualPage;
        infoPage.search = search;
        this.appContainer.innerHTML = '';
        this.appContainer.innerHTML = tableLayout;

        const titleTag: InterfaceElement = document.getElementById('datatable-title-tag');
        const tableBody: InterfaceElement = document.getElementById('datatable-body');
        tableBody.innerHTML = 'Cargando...';

        let customersArray = await GetCustomers();
        const groupDetail = await getGroupControllerActive()
        titleTag.textContent = `GRUPO: ${groupDetail?.valid ? groupDetail?.groupName ?? '' : ''}`;

        tableBody.innerHTML = tableLayoutTemplate.repeat(tableRows);

        this.load(tableBody, currentPage, customersArray);
        new filterDataByHeaderType().filter();
        this.searchCustomer(tableBody);
        this.pagination(customersArray, tableRows, infoPage.currentPage);
    };

    public load(tableBody: any, currentPage: any, customers: any) {
        tableBody.innerHTML = ''; // clean table
        if (!customers || customers.length === 0) {
            let row = document.createElement('TR');
            row.innerHTML = `
                <td>No existen datos</td>
                <td></td>
                <td></td>
            `;
            tableBody.appendChild(row);
        }
        else {
            for (let i = 0; i < customers.length; i++) {
                let item = customers[i];
                let customerId = item?.customerId ?? item?.id;
                let name = item?.customerName ?? item?.name ?? '';
                let ruc = item?.customerRuc ?? item?.ruc ?? '';
                let state = item?.customerState ?? item?.state?.name ?? '';
                let isControllerTag = item?.isController ? ' <span class="tag" style="background-color:#4CAF50;color:white;padding:2px 6px;border-radius:4px;font-size:0.8em">Controlador</span>' : '';

                let row = document.createElement('TR');
                row.innerHTML += `
                    <td style="white-space: nowrap">${name}${isControllerTag}</td>
                    <td>${ruc}</td>
                    <td class="tag"><span>${state}</span></td>
                    <td>
                        <button class="button" id="entity-details" data-entityId="${customerId}">
                            <i class="table_icon fa-regular fa-check"></i>
                        </button>
                    </td>
                `;
                tableBody.appendChild(row);
                drawTagsIntoTables();
            }
            this.previewVisit();
        }
    };

    public searchCustomer = async (tableBody: InterfaceElement) => {
        const search: InterfaceElement = document.getElementById('search');
        const btnSearch: InterfaceElement = document.getElementById('btnSearch');
        search.value = infoPage.search;

        btnSearch.addEventListener('click', async () => {
            new SelectCustomer().render(Config.offset, Config.currentPage, search.value.toLowerCase().trim());
        });
    };

    public previewVisit = async () => {
        const openButtons = document.querySelectorAll('#entity-details');
        openButtons.forEach((openButton: any) => {
            const entityId = openButton.dataset.entityid;
            openButton.addEventListener('click', () => {
                const customerId = localStorage.getItem('customer_id');
                if (customerId == null) {
                    localStorage.setItem('customer_id', entityId);
                }
                else {
                    localStorage.removeItem('customer_id');
                    localStorage.setItem('customer_id', entityId);
                }
                window.location.reload();
            });
        });
    };

    public pagination = (items: any, limitRows: any, currentPage: any) => {
        const paginationWrapper: InterfaceElement = document.getElementById('pagination-container');
        paginationWrapper.innerHTML = '';
        let pageCount: any = Math.ceil(infoPage.count / limitRows);
        let button;

        if (pageCount <= Config.maxLimitPage) {
            for (let i = 1; i < pageCount + 1; i++) {
                button = setupButtons(i);
                paginationWrapper.appendChild(button);
            }
            fillBtnPagination(currentPage, Config.colorPagination);
        }
        else {
            pagesOptions(items, currentPage);
        }

        function setupButtons(page: any) {
            const button: InterfaceElement = document.createElement('button');
            button.classList.add('pagination_button');
            button.setAttribute("name", "pagination-button");
            button.setAttribute("id", "btnPag" + page);
            button.innerText = page;
            button.addEventListener('click', () => {
                infoPage.offset = Config.tableRows * (page - 1);
                currentPage = page;
                new SelectCustomer().render(infoPage.offset, currentPage, infoPage.search);
            });
            return button;
        }

        function pagesOptions(items: any, currentPage: any) {
            paginationWrapper.innerHTML = '';
            let pages = pageNumbers(items, Config.maxLimitPage, currentPage);
            const prevButton: InterfaceElement = document.createElement('button');
            prevButton.classList.add('pagination_button');
            prevButton.innerText = "<<";
            paginationWrapper.appendChild(prevButton);

            const nextButton: InterfaceElement = document.createElement('button');
            nextButton.classList.add('pagination_button');
            nextButton.innerText = ">>";

            for (let i = 0; i < pages.length; i++) {
                if (pages[i] > 0 && pages[i] <= pageCount) {
                    button = setupButtons(pages[i]);
                    paginationWrapper.appendChild(button);
                }
            }
            paginationWrapper.appendChild(nextButton);
            fillBtnPagination(currentPage, Config.colorPagination);
            setupButtonsEvents(prevButton, nextButton);
        }

        function setupButtonsEvents(prevButton: InterfaceElement, nextButton: InterfaceElement) {
            prevButton.addEventListener('click', () => {
                new SelectCustomer().render(Config.offset, Config.currentPage, infoPage.search);
            });
            nextButton.addEventListener('click', () => {
                infoPage.offset = Config.tableRows * (pageCount - 1);
                new SelectCustomer().render(infoPage.offset, pageCount, infoPage.search);
            });
        }
    };
}
